const GERMAN_CHARS = new Set([..."äöüßÄÖÜ"]);
const GERMAN_QUESTION_PREFIXES = [
  "wie ", "was ", "warum ", "wann ", "wo ", "wer ", "welche ", "welches ",
  "kann ", "muss ", "darf ", "ist ", "sind ", "wird ", "werden ",
  "dürfen ", "können ", "müssen ", "ohne ", "wenn ", "nicht ",
];
const ENGLISH_QUESTION_PREFIXES = [
  "what ", "why ", "when ", "where ", "who ", "which ", "how ",
  "can ", "must ", "may ", "is ", "are ", "will ", "does ", "do ",
  "should ", "could ", "would ", "without ", "if ", "not ",
];
const GERMAN_STOPWORDS = new Set([
  "der", "die", "das", "und", "ist", "wie", "kann", "muss", "darf",
  "wird", "werden", "eine", "einen", "einem", "einer", "nicht", "auf",
  "mit", "für", "von", "bei", "ohne", "wenn", "was", "wer", "wo",
  "warum", "wieso", "arbeitgeber", "arbeitnehmer", "betriebsrat",
  "kündigung", "gehalt", "urlaub", "dürfen", "können", "müssen",
]);
const ENGLISH_STOPWORDS = new Set([
  "the", "is", "can", "does", "do", "must", "may", "will", "a", "an",
  "not", "on", "with", "for", "from", "at", "without", "if", "what",
  "who", "where", "why", "employer", "employee", "works", "council",
  "termination", "salary", "vacation", "how", "which", "when",
]);

function detectLanguage(text) {
  if (!text || !text.trim()) return "en";
  const lowered = text.toLowerCase();
  const hasGermanChars = [...text].some((ch) => GERMAN_CHARS.has(ch));
  const hasEnglishPrefix = ENGLISH_QUESTION_PREFIXES.some((p) => lowered.startsWith(p));
  const hasGermanPrefix = GERMAN_QUESTION_PREFIXES.some((p) => lowered.startsWith(p));

  if (hasEnglishPrefix && !hasGermanPrefix) return "en";
  if (hasGermanPrefix && !hasEnglishPrefix) return "de";
  if (hasGermanChars && !hasEnglishPrefix) return "de";

  const words = new Set(lowered.match(/[a-zA-Z]+/g) || []);
  let deScore = 0;
  let enScore = 0;
  for (const w of words) {
    if (GERMAN_STOPWORDS.has(w)) deScore++;
    if (ENGLISH_STOPWORDS.has(w)) enScore++;
  }
  if (deScore === enScore) return "en";
  return deScore > enScore ? "de" : "en";
}

